; clash120.asm -- appendix I: chapter 1, question 2: clash_ball with the ball at x = 120
; generated by genI.py
        INCLUDE "msx.inc"
        OUTPUT "clash120.rom"
        ORG $4000
        CART_HEADER init
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; 16 KB, display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, 1          ; border colour
        VRAM_WRITE 0            ; clear all 16 KB
        ld bc, $4000
.clear: xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clear
        VRAM_WRITE $1800        ; names: 0-255 in each third
        ld c, 3
.third: xor a
.name:  out (VDP_DATA), a
        inc a
        jr nz, .name
        dec c
        jr nz, .third
        VRAM_WRITE $2000        ; colours: 0x21 everywhere
        ld bc, 6144
.col:   ld a, $21
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $1B00        ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the grass: two dots in every byte
        ld bc, 6144
        ld d, 0
grass:  ld a, d
        and 3
        ld hl, dots
        add a, l
        ld l, a
        ld a, (hl)
        out (VDP_DATA), a
        inc d
        dec bc
        ld a, b
        or c
        jr nz, grass
        ld hl, cells            ; the ball, drawn into the cells it covers
        ld c, 6
cell:   ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld b, 8
pixels: ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz pixels
        dec c
        jr nz, cell
        ld hl, strips           ; the colour strips under the ball: white ink
        ld b, 32
strip:  ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld a, $F1               ; ink 15 (white), paper 1 (black)
        out (VDP_DATA), a
        djnz strip
        VDP_REG 1, $C0          ; display on
done:   jr done
        ALIGN 4
dots:   db $88, $22, $44, $11
cells:                          ; address, then the 8 bytes of each cell
        dw $0B78
        db $88, $22, $44, $11, $89, $2F, $5F, $3F
        dw $0B80
        db $88, $22, $44, $11, $88, $F2, $FC, $FD
        dw $0C78
        db $FF, $7F, $7F, $FF, $FF, $7F, $7F, $7F
        dw $0C80
        db $FE, $FE, $FE, $FF, $FF, $FE, $FE, $FF
        dw $0D78
        db $BF, $3F, $4F, $11, $88, $22, $44, $11
        dw $0D80
        db $FC, $FA, $F4, $91, $88, $22, $44, $11
strips:
        dw $2B7C
        dw $2B7D
        dw $2B7E
        dw $2B7F
        dw $2B84
        dw $2B85
        dw $2B86
        dw $2B87
        dw $2C78
        dw $2C79
        dw $2C7A
        dw $2C7B
        dw $2C7C
        dw $2C7D
        dw $2C7E
        dw $2C7F
        dw $2C80
        dw $2C81
        dw $2C82
        dw $2C83
        dw $2C84
        dw $2C85
        dw $2C86
        dw $2C87
        dw $2D78
        dw $2D79
        dw $2D7A
        dw $2D7B
        dw $2D80
        dw $2D81
        dw $2D82
        dw $2D83
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
